      ? parseLocalDate(this.element.dateTime)
      : new Date(this.element.dateTime)

    if (!Number.isNaN(timestamp.getTime())) {
      const rendered = formatLocalTime(timestamp, this.formatValue)
      this.element.textContent = rendered
      this.element.setAttribute("aria-label", rendered)
    }
  }
}

  test "local_time_tag sends a timezone-independent raw timestamp to the browser" do
    timestamp = Time.utc(2024, 9, 12, 20, 42)
    new_york_html = Time.use_zone("America/New_York") { local_time_tag timestamp, format: "comment" }
    tokyo_html = Time.use_zone("Asia/Tokyo") { local_time_tag timestamp, format: "comment" }

    assert_equal new_york_html, tokyo_html
    selector = [
      "time[datetime='2024-09-12T20:42:00Z']",
      "[data-controller='local-time']",
      "[data-local-time-format-value='comment']"
    ].join
    assert_select parse(new_york_html), selector, text: "2024-09-12T20:42:00Z"
  end

